<?php

/*
 * D1 (owner-approved Option C, 2026-11-09): the forum guard reproduces vBulletin's two session IP checks —
 * idhash from ALT_IP and session.host against IPADDRESS — from the raw server values, validated configuration,
 * read-only. Expected values come from VbulletinIpGoldenVectors, generated by executing the legacy vBulletin source.
 */

use App\Domain\Identity\Guards\VbulletinSessionGuard;
use App\Domain\Identity\Models\VbUser;
use App\Domain\Identity\Support\VbulletinSessionBinding;
use App\Domain\Identity\Support\VbulletinSessionBindingConfigurationException;
use Illuminate\Database\Events\QueryExecuted;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Log;
use Tests\Support\Fixtures\VbulletinIpAdversarialVectors;
use Tests\Support\Fixtures\VbulletinIpGoldenVectors;
use Tests\Support\Fixtures\VbulletinSchema;
use Tests\Support\InMemoryConnection;
use Tests\Support\MobileHarness;

uses(RefreshDatabase::class);

const VBB_SALT = 'binding-test-salt';
const VBB_UA = 'BindingUA/1.0';
const VBB_HASH = '0123456789abcdef0123456789abcdef';

/** A request carrying exactly these server variables (no default User-Agent unless given). */
function vbbRequest(array $server, ?string $sessionHash = VBB_HASH): Request
{
    $request = Request::create('/', 'GET', server: $server);
    if (! array_key_exists('HTTP_USER_AGENT', $server)) {
        $request->server->remove('HTTP_USER_AGENT');
        $request->headers->remove('User-Agent');
    }
    if (! array_key_exists('REMOTE_ADDR', $server)) {
        $request->server->remove('REMOTE_ADDR');      // Request::create() injects 127.0.0.1 by default
    }
    if ($sessionHash !== null) {
        $request->cookies->set('bb_sessionhash', $sessionHash);
    }

    return $request;
}

function vbbConfigure(mixed $ipcheck = 1, string $proxyList = '', string $proxyHeader = '', bool $allowUnbound = false, int|string $timeout = 900): void
{
    config([
        'services.vbulletin.ipcheck' => $ipcheck,
        'services.vbulletin.ipcheck_allow_unbound' => $allowUnbound,
        'services.vbulletin.proxy_ip_list' => $proxyList,
        'services.vbulletin.proxy_ip_header' => $proxyHeader,
        'services.vbulletin.cookie_timeout' => $timeout,
    ]);
}

function vbbConfigureVector(array $vector): void
{
    vbbConfigure($vector['ipcheck'], $vector['proxy_ip_list'], $vector['proxy_ip_header'], $vector['ipcheck'] === 4);
}

/** The session row vBulletin itself would have written for this request (session.php:760-771). */
function vbbStoreSession(string $idhash, string $host, int $age = 60, int $userid = 501): void
{
    DB::connection('vbulletin')->table('session')->insert([
        'sessionhash' => VBB_HASH, 'userid' => $userid, 'idhash' => $idhash, 'host' => $host, 'lastactivity' => time() - $age,
    ]);
}

function vbbUser(Request $request): ?VbUser
{
    return (new VbulletinSessionGuard($request))->user();
}

function vbbVectors(): array
{
    return array_map(fn ($v) => [$v], VbulletinIpGoldenVectors::all());
}

function vbbAdversarialVectors(): array
{
    return array_map(fn ($v) => [$v], VbulletinIpAdversarialVectors::all());
}

function vbbAdversarial(string $name): array
{
    return VbulletinIpAdversarialVectors::all()[$name];
}

beforeEach(function () {
    InMemoryConnection::setup('vbulletin', ['user' => VbulletinSchema::user(), 'session' => VbulletinSchema::session()]);
    DB::connection('vbulletin')->table('user')->insert(['userid' => 501, 'username' => 'عضو', 'password' => 'stored-hash-501']);
    config(['services.vbulletin.cookie_salt' => VBB_SALT]);
    vbbConfigure();
});

// ================================================================ golden vectors (executed vBulletin source)

it('reproduces vBulletin IPADDRESS, ALT_IP, User-Agent, idhash and host prefix for every golden vector', function (array $vector) {
    vbbConfigureVector($vector);
    $binding = VbulletinSessionBinding::fromConfig();
    $request = vbbRequest($vector['server']);
    $expected = $vector['expected'];

    expect($binding->addresses($request))->toBe(['ipAddress' => $expected['IPADDRESS'], 'altIp' => $expected['ALT_IP']])
        ->and($binding->userAgent($request))->toBe($expected['userAgent'])
        ->and($binding->idHash($request))->toBe($expected['idhash'])
        ->and($binding->ipSubstring($binding->addresses($request)['ipAddress']))->toBe($expected['host_substr']);
})->with(vbbVectors());

it('accepts the session vBulletin created for that same request, for every golden vector', function (array $vector) {
    vbbConfigureVector($vector);
    vbbStoreSession($vector['expected']['idhash'], $vector['expected']['IPADDRESS']);

    expect(vbbUser(vbbRequest($vector['server']))?->userid)->toBe(501);
})->with(vbbVectors());

// ================================================================ the D1 fix

it('accepts a forum session created behind a public X-Forwarded-For — rejected by the previous REMOTE_ADDR-only hash', function () {
    $vector = VbulletinIpGoldenVectors::all()['public X-Forwarded-For'];
    vbbStoreSession($vector['expected']['idhash'], $vector['expected']['IPADDRESS']);

    $previousAlgorithm = md5(VbulletinIpGoldenVectors::all()['public X-Forwarded-For']['server']['HTTP_USER_AGENT'].'203.0.113');

    expect($previousAlgorithm)->not->toBe($vector['expected']['idhash'])
        ->and(vbbUser(vbbRequest($vector['server']))?->userid)->toBe(501);
});

it('accepts a CF-Connecting-IP session (Cloudflare header takes precedence over X-Forwarded-For)', function () {
    $vector = VbulletinIpGoldenVectors::all()['CF-Connecting-IP takes precedence over X-Forwarded-For'];
    vbbStoreSession($vector['expected']['idhash'], $vector['expected']['IPADDRESS']);

    expect($vector['expected']['ALT_IP'])->toBe('198.51.100.99')
        ->and(vbbUser(vbbRequest($vector['server']))?->userid)->toBe(501);
});

// ================================================================ spoofing and the host check

it('rejects a stolen cookie replayed from another network with spoofed CF-Connecting-IP / X-Forwarded-For (host check)', function (string $header) {
    $victim = VbulletinIpGoldenVectors::all()['direct IPv4, ipcheck 1'];
    vbbStoreSession($victim['expected']['idhash'], $victim['expected']['IPADDRESS']);
    $attacker = vbbRequest(['REMOTE_ADDR' => '198.51.100.66', 'HTTP_USER_AGENT' => $victim['server']['HTTP_USER_AGENT'], $header => '203.0.113.42']);

    // The spoofed header reproduces the victim's idhash exactly — only the host check stops the replay.
    expect(VbulletinSessionBinding::fromConfig()->idHash($attacker))->toBe($victim['expected']['idhash'])
        ->and(vbbUser($attacker))->toBeNull();
})->with(['HTTP_CF_CONNECTING_IP', 'HTTP_X_FORWARDED_FOR']);

it('rejects a wrong session.host even when the idhash matches, and a wrong idhash even when the host matches', function () {
    $vector = VbulletinIpGoldenVectors::all()['direct IPv4, ipcheck 1'];

    vbbStoreSession($vector['expected']['idhash'], '198.51.100.1');
    expect(vbbUser(vbbRequest($vector['server'])))->toBeNull();

    DB::connection('vbulletin')->table('session')->delete();
    vbbStoreSession(md5('something else'), $vector['expected']['IPADDRESS']);
    expect(vbbUser(vbbRequest($vector['server'])))->toBeNull();

    DB::connection('vbulletin')->table('session')->delete();
    vbbStoreSession($vector['expected']['idhash'], '');               // a row without a host never matches
    expect(vbbUser(vbbRequest($vector['server'])))->toBeNull();
});

it('rejects a different User-Agent; a missing User-Agent hashes as "vBulletin" and an empty one does not', function () {
    $missing = VbulletinIpGoldenVectors::all()['missing User-Agent'];
    vbbStoreSession($missing['expected']['idhash'], $missing['expected']['IPADDRESS']);

    expect(vbbUser(vbbRequest($missing['server']))?->userid)->toBe(501)
        ->and(vbbUser(vbbRequest(['REMOTE_ADDR' => '203.0.113.42', 'HTTP_USER_AGENT' => ''])))->toBeNull()
        ->and(vbbUser(vbbRequest(['REMOTE_ADDR' => '203.0.113.42', 'HTTP_USER_AGENT' => 'OtherBrowser/2.0'])))->toBeNull();
});

// ================================================================ ipcheck

it('applies ipcheck 0–3 as vBulletin does (octets kept = 4 - ipcheck)', function (int $ipcheck, string $sameNetwork, string $otherNetwork) {
    vbbConfigure($ipcheck);
    $creating = vbbRequest(['REMOTE_ADDR' => '203.0.113.42', 'HTTP_USER_AGENT' => VBB_UA]);
    vbbStoreSession(VbulletinSessionBinding::fromConfig()->idHash($creating), '203.0.113.42');

    expect(vbbUser(vbbRequest(['REMOTE_ADDR' => $sameNetwork, 'HTTP_USER_AGENT' => VBB_UA]))?->userid)->toBe(501)
        ->and(vbbUser(vbbRequest(['REMOTE_ADDR' => $otherNetwork, 'HTTP_USER_AGENT' => VBB_UA])))->toBeNull();
})->with([
    'ipcheck 0 (full address)' => [0, '203.0.113.42', '203.0.113.43'],
    'ipcheck 1 (/24)' => [1, '203.0.113.200', '203.0.114.42'],
    'ipcheck 2 (/16)' => [2, '203.0.250.1', '203.1.113.42'],
    'ipcheck 3 (/8)' => [3, '203.250.1.1', '204.0.113.42'],
]);

it('IPv6 sessions are bound to the whole canonical address', function () {
    $vector = VbulletinIpGoldenVectors::all()['direct IPv6 (canonicalised)'];
    vbbStoreSession($vector['expected']['idhash'], $vector['expected']['IPADDRESS']);

    expect(vbbUser(vbbRequest(['REMOTE_ADDR' => '2001:db8::1', 'HTTP_USER_AGENT' => $vector['server']['HTTP_USER_AGENT']]))?->userid)->toBe(501)
        ->and(vbbUser(vbbRequest(['REMOTE_ADDR' => '2001:db8::2', 'HTTP_USER_AGENT' => $vector['server']['HTTP_USER_AGENT']])))->toBeNull();
});

it('refuses ipcheck=4 (no IP binding) unless explicitly approved, and logs why', function () {
    Log::spy();
    vbbConfigure(4);
    vbbStoreSession(md5(VBB_UA), '203.0.113.42');

    expect(vbbUser(vbbRequest(['REMOTE_ADDR' => '198.51.100.66', 'HTTP_USER_AGENT' => VBB_UA])))->toBeNull();
    Log::shouldHaveReceived('error')->once()->withArgs(fn ($message, $context) => str_contains($message, 'session binding configuration refused')
        && str_contains($context['reason'], 'VBULLETIN_IPCHECK_ALLOW_UNBOUND'));

    vbbConfigure(4, allowUnbound: true);
    expect(vbbUser(vbbRequest(['REMOTE_ADDR' => '198.51.100.66', 'HTTP_USER_AGENT' => VBB_UA]))?->userid)->toBe(501);
});

it('refuses invalid ipcheck values', function (mixed $value) {
    vbbConfigure($value);

    expect(fn () => VbulletinSessionBinding::fromConfig())->toThrow(VbulletinSessionBindingConfigurationException::class, 'VBULLETIN_IPCHECK');
})->with(['5', '-1', 'abc', '1.5', '', ' ', 99, -1, [[1]]]);

// ================================================================ cookie timeout

it('uses the configured cookie timeout and refuses invalid values', function () {
    vbbConfigure(timeout: '1800');
    $vector = VbulletinIpGoldenVectors::all()['direct IPv4, ipcheck 1'];
    vbbStoreSession($vector['expected']['idhash'], '203.0.113.42', age: 1000);
    expect(vbbUser(vbbRequest($vector['server']))?->userid)->toBe(501);

    vbbConfigure();                                  // default 900: the same 1000-second-old session is expired
    expect(vbbUser(vbbRequest($vector['server'])))->toBeNull();

    foreach (['0', 'x', '-5', '9.5', ''] as $bad) {
        vbbConfigure(timeout: $bad);
        expect(fn () => VbulletinSessionBinding::fromConfig())->toThrow(VbulletinSessionBindingConfigurationException::class, 'VBULLETIN_COOKIE_TIMEOUT');
    }
});

it('rejects an expired session at exactly the timeout, and a missing session row', function () {
    $vector = VbulletinIpGoldenVectors::all()['direct IPv4, ipcheck 1'];
    vbbStoreSession($vector['expected']['idhash'], '203.0.113.42', age: 900);

    expect(vbbUser(vbbRequest($vector['server'])))->toBeNull()
        ->and(vbbUser(vbbRequest($vector['server'], 'ffffffffffffffffffffffffffffffff')))->toBeNull();
});

// ================================================================ proxy list / header

it('a proxied session is accepted only when the proxy list is mirrored (fails closed otherwise)', function (string $name) {
    $vector = VbulletinIpGoldenVectors::all()[$name];
    vbbStoreSession($vector['expected']['idhash'], $vector['expected']['IPADDRESS']);

    vbbConfigureVector($vector);
    expect(vbbUser(vbbRequest($vector['server']))?->userid)->toBe(501);

    vbbConfigure();                                  // forum proxy list not mirrored in Laravel
    expect(vbbUser(vbbRequest($vector['server'])))->toBeNull();
})->with(['proxy list exact match, header set', 'proxy list wildcard match, header set', 'proxy list match, no header configured (alt-IP rules then flip)']);

it('refuses proxyiplist=all (and an all-matching "*"), and malformed lists', function (string $list, string $reason) {
    Log::spy();
    vbbConfigure(proxyList: $list, proxyHeader: 'HTTP_X_CLIENT_IP');
    vbbStoreSession(md5(VBB_UA.'10.9.8'), '198.51.100.9');

    expect(fn () => VbulletinSessionBinding::fromConfig())->toThrow(VbulletinSessionBindingConfigurationException::class, $reason)
        ->and(vbbUser(vbbRequest(['REMOTE_ADDR' => '10.9.8.7', 'HTTP_USER_AGENT' => VBB_UA, 'HTTP_X_CLIENT_IP' => '198.51.100.9'])))->toBeNull();
    Log::shouldHaveReceived('error')->once();
})->with([
    'all' => ['all', 'may not trust every address'],
    'ALL' => ['ALL', 'may not trust every address'],
    'padded all' => [' all ', 'may not trust every address'],
    'bare *' => ['*', 'may not trust every address'],
    'all inside a list' => ['10.9.8.7, all', 'may not trust every address'],
    'empty entry' => ['10.0.0.1,,10.0.0.2', 'malformed or empty'],
    'not an IP' => ['not-an-ip', 'malformed or empty'],
    'bad wildcard' => ['10.9.*x', 'malformed or empty'],
    'leading wildcard' => ['*10.9', 'malformed or empty'],
]);

it('refuses an invalid proxy header name; ignores the header when the client is not a listed proxy', function () {
    foreach (['X-Client-IP', 'http_x_client_ip', '1HTTP', 'HTTP X'] as $bad) {
        vbbConfigure(proxyList: '10.9.*', proxyHeader: $bad);
        expect(fn () => VbulletinSessionBinding::fromConfig())->toThrow(VbulletinSessionBindingConfigurationException::class, 'VBULLETIN_PROXY_IP_HEADER');
    }

    $vector = VbulletinIpGoldenVectors::all()['proxy list does not match'];
    vbbConfigureVector($vector);
    expect(VbulletinSessionBinding::fromConfig()->addresses(vbbRequest($vector['server'])))
        ->toBe(['ipAddress' => '203.0.113.42', 'altIp' => '203.0.113.42']);
});

it('accepts config:cache-style string values and integers alike', function () {
    vbbConfigure('1', '10.9.8.7, 10.10.*', 'HTTP_X_CLIENT_IP', false, '900');
    $fromStrings = VbulletinSessionBinding::fromConfig();
    vbbConfigure(1, '10.9.8.7, 10.10.*', 'HTTP_X_CLIENT_IP', false, 900);
    $fromIntegers = VbulletinSessionBinding::fromConfig();
    $request = vbbRequest(['REMOTE_ADDR' => '10.10.1.1', 'HTTP_USER_AGENT' => VBB_UA, 'HTTP_X_CLIENT_IP' => '198.51.100.9']);

    expect($fromStrings->addresses($request))->toBe($fromIntegers->addresses($request))
        ->and($fromStrings->addresses($request))->toBe(['ipAddress' => '198.51.100.9', 'altIp' => '10.10.1.1'])
        ->and($fromStrings->cookieTimeout())->toBe(900);
});

