it('never writes to the forum database and never logs the cookie salt', function () {
    Log::spy();
    $statements = [];
    DB::connection('vbulletin')->listen(function (QueryExecuted $q) use (&$statements) {
        $statements[] = $q->sql;
    });
    $vector = VbulletinIpGoldenVectors::all()['public X-Forwarded-For'];
    vbbStoreSession($vector['expected']['idhash'], $vector['expected']['IPADDRESS'], age: 300);
    $before = DB::connection('vbulletin')->table('session')->first();
    $statements = [];

    expect(vbbUser(vbbRequest($vector['server']))?->userid)->toBe(501);
    vbbConfigure('bad');
    vbbUser(vbbRequest($vector['server']));

    expect(array_filter($statements, fn ($sql) => preg_match('/^\s*(insert|update|delete|replace)\b/i', $sql)))->toBe([])
        ->and(DB::connection('vbulletin')->table('session')->first())->toEqual($before);
    Log::shouldHaveReceived('error')->withArgs(fn ($message, $context) => ! str_contains(json_encode($context), VBB_SALT));
});

it('through the real web stack, a member behind a public X-Forwarded-For is recognised; Laravel trusted proxies stay off', function () {
    MobileHarness::setUp();
    InMemoryConnection::setup('vbulletin', ['user' => VbulletinSchema::user(), 'session' => VbulletinSchema::session()]);
    DB::connection('vbulletin')->table('user')->insert(['userid' => 501, 'username' => 'عضو', 'password' => 'stored-hash-501']);
    $vector = VbulletinIpGoldenVectors::all()['public X-Forwarded-For'];
    vbbStoreSession($vector['expected']['idhash'], $vector['expected']['IPADDRESS']);

    $html = $this->withServerVariables(['REMOTE_ADDR' => '203.0.113.42', 'HTTP_USER_AGENT' => $vector['server']['HTTP_USER_AGENT']])
        ->withHeader('X-Forwarded-For', '198.51.100.7')
        ->withUnencryptedCookie('bb_sessionhash', VBB_HASH)
        ->get('/mobiles-admobile.htm')->assertOk()->getContent();

    expect($html)->not->toContain('للأعضاء المسجلين فقط')
        ->and(config('trustedproxy.proxies'))->toBeNull();
});

// ================================================================ D1 closure follow-up (2026-11-09): adversarial vectors

it('reproduces vBulletin for every adversarial golden vector (proxied fallbacks, IPv6, ports, CGNAT, REMOTE_ADDR edges)', function (array $vector) {
    vbbConfigureVector($vector);
    $binding = VbulletinSessionBinding::fromConfig();
    $request = vbbRequest($vector['server']);
    $expected = $vector['expected'];

    expect($binding->addresses($request))->toBe(['ipAddress' => $expected['IPADDRESS'], 'altIp' => $expected['ALT_IP']])
        ->and($binding->userAgent($request))->toBe($expected['userAgent'])
        ->and($binding->idHash($request))->toBe($expected['idhash'])
        ->and($binding->ipSubstring($binding->addresses($request)['ipAddress']))->toBe($expected['host_substr']);
})->with(vbbAdversarialVectors());

it('accepts the session vBulletin created for that same request, for every adversarial vector', function (array $vector) {
    vbbConfigureVector($vector);
    vbbStoreSession($vector['expected']['idhash'], $vector['expected']['IPADDRESS']);

    expect(vbbUser(vbbRequest($vector['server']))?->userid)->toBe(501);
})->with(vbbAdversarialVectors());

it('proxied fallbacks: a multi-value, missing or invalid configured header falls back to the alt-IP rules', function () {
    expect(vbbAdversarial('proxied: multi-value configured header falls back to alt-IP rules')['expected']['IPADDRESS'])->toBe('203.0.113.50')
        ->and(vbbAdversarial('proxied: missing configured header falls back to CF-Connecting-IP')['expected']['IPADDRESS'])->toBe('198.51.100.77')
        ->and(vbbAdversarial('proxied: invalid configured header falls back to X-Forwarded-For')['expected']['IPADDRESS'])->toBe('198.51.100.88');

    foreach (['proxied: multi-value configured header falls back to alt-IP rules', 'proxied: missing configured header falls back to CF-Connecting-IP', 'proxied: invalid configured header falls back to X-Forwarded-For'] as $name) {
        $vector = vbbAdversarial($name);
        vbbConfigureVector($vector);
        expect(VbulletinSessionBinding::fromConfig()->addresses(vbbRequest($vector['server'])))
            ->toBe(['ipAddress' => $vector['expected']['IPADDRESS'], 'altIp' => '10.9.8.7']);
    }
});

it('F1 (documented production precondition): behind an UNSAFE proxy a spoofed fallback header satisfies both checks — exactly as in vBulletin', function () {
    $victim = vbbAdversarial('proxied: victim session through a proxy that sets the header');
    $attacker = vbbAdversarial('proxied: attacker through an unsafe proxy (header absent, client CF-Connecting-IP passed through)');
    vbbConfigureVector($victim);
    vbbStoreSession($victim['expected']['idhash'], $victim['expected']['IPADDRESS']);

    // The attacker's request — through the listed proxy, which neither set the configured header nor stripped the
    // client's CF-Connecting-IP — reproduces the victim's IPADDRESS and ALT_IP, so the stolen cookie is ACCEPTED.
    // Proxy mode is therefore only safe when the proxy overwrites the header and sanitises client headers.
    expect($attacker['expected']['idhash'])->toBe($victim['expected']['idhash'])
        ->and($attacker['expected']['IPADDRESS'])->toBe($victim['expected']['IPADDRESS'])
        ->and(vbbUser(vbbRequest($attacker['server']))?->userid)->toBe(501);

    // The same spoofed header sent DIRECTLY (not through a listed proxy) is rejected: the host check binds REMOTE_ADDR.
    expect(vbbUser(vbbRequest(['REMOTE_ADDR' => '198.51.100.66', 'HTTP_USER_AGENT' => $attacker['server']['HTTP_USER_AGENT'], 'HTTP_CF_CONNECTING_IP' => '198.51.100.9'])))->toBeNull();

    // And with the default (empty) proxy list, the attacker's request through the proxy is not "proxied" at all.
    vbbConfigure();
    expect(vbbUser(vbbRequest($attacker['server'])))->toBeNull();
});

it('ipcheck=2 numeric prefixes: vBulletin\'s loose == would accept "1.1" vs "1.10"; Laravel\'s strict === rejects (deliberate)', function () {
    $created = vbbAdversarial('ipcheck 2: session created at 1.10.5.5 behind public X-Forwarded-For');
    $later = vbbAdversarial('ipcheck 2: later request from 1.1.7.7 behind the same X-Forwarded-For');
    vbbConfigure(2);
    vbbStoreSession($created['expected']['idhash'], $created['expected']['IPADDRESS']);

    // idhash matches (same ALT_IP prefix 8.8); only the host prefixes differ: "1.10" vs "1.1".
    expect($later['expected']['idhash'])->toBe($created['expected']['idhash'])
        ->and([$created['expected']['host_substr'], $later['expected']['host_substr']])->toBe(['1.10', '1.1'])
        // vBulletin compares with == (session.php:347): PHP treats both as numeric strings and finds them equal.
        ->and($created['expected']['host_substr'] == $later['expected']['host_substr'])->toBeTrue()
        // Laravel compares with === : a different /16 is a different network — rejected (stricter, never weaker).
        ->and(vbbUser(vbbRequest($later['server'])))->toBeNull();
});

it('IPv6 CF-Connecting-IP and uppercase IPv6 X-Forwarded-For are canonicalised; ULA and link-local are skipped', function () {
    expect(vbbAdversarial('IPv6 CF-Connecting-IP (canonicalised)')['expected']['ALT_IP'])->toBe('2606:4700::abcd')
        ->and(vbbAdversarial('uppercase IPv6 in X-Forwarded-For (canonicalised)')['expected']['ALT_IP'])->toBe('2606:4700::abcd')
        ->and(vbbAdversarial('IPv6 ULA and link-local skipped in X-Forwarded-For')['expected']['ALT_IP'])->toBe('2606:4700::1')
        ->and(vbbAdversarial('IPv6 ULA / link-local only: falls back to REMOTE_ADDR')['expected']['ALT_IP'])->toBe('203.0.113.42')
        ->and(vbbAdversarial('ULA CF-Connecting-IP ignored')['expected']['ALT_IP'])->toBe('8.8.4.4');
});

it('an IPv4 with a port is not an IP (skipped); CGNAT 100.64/10 counts as public, as in vBulletin', function () {
    expect(vbbAdversarial('IPv4 with port in X-Forwarded-For is not an IP')['expected']['ALT_IP'])->toBe('203.0.113.42')
        ->and(vbbAdversarial('IPv4 with port skipped, next public entry used')['expected']['ALT_IP'])->toBe('8.8.8.8')
        ->and(vbbAdversarial('CGNAT 100.64/10 in X-Forwarded-For counts as public')['expected']['ALT_IP'])->toBe('100.64.1.2');
});

it('REMOTE_ADDR edge cases match vBulletin: missing gives empty addresses, surrounding whitespace is trimmed after the proxy-list check', function () {
    expect(vbbAdversarial('missing REMOTE_ADDR')['expected'])->toMatchArray(['IPADDRESS' => '', 'ALT_IP' => '', 'host_substr' => ''])
        ->and(vbbAdversarial('whitespace around REMOTE_ADDR is trimmed')['expected']['IPADDRESS'])->toBe('203.0.113.42')
        // vBulletin matches the proxy list against the raw REMOTE_ADDR (before trimming): " 10.9.8.7 " is not proxied.
        ->and(vbbAdversarial('whitespace REMOTE_ADDR does not match an exact proxy list entry')['expected'])->toMatchArray(['IPADDRESS' => '10.9.8.7', 'ALT_IP' => '10.9.8.7']);

    // A missing REMOTE_ADDR never matches a session stored for a real address.
    $direct = VbulletinIpGoldenVectors::all()['direct IPv4, ipcheck 1'];
    vbbStoreSession($direct['expected']['idhash'], $direct['expected']['IPADDRESS']);
    expect(vbbUser(vbbRequest(['HTTP_USER_AGENT' => $direct['server']['HTTP_USER_AGENT']])))->toBeNull();
});

// ================================================================ Part 3: existing security still holds

it('Laravel Trusted Proxies and Trusted Hosts remain unconfigured', function () {
    $bootstrap = (string) file_get_contents(base_path('bootstrap/app.php'));

    expect(file_exists(config_path('trustedproxy.php')))->toBeFalse()
        ->and(config('trustedproxy.proxies'))->toBeNull()
        ->and($bootstrap)->not->toContain('trustProxies(')->not->toContain('trustHosts(');
});

it('the default (empty) proxy list keeps both IP checks mandatory', function () {
    vbbConfigure();
    $vector = VbulletinIpGoldenVectors::all()['public X-Forwarded-For'];

    vbbStoreSession($vector['expected']['idhash'], '198.51.100.1');                     // idhash right, host wrong
    expect(vbbUser(vbbRequest($vector['server'])))->toBeNull();

    DB::connection('vbulletin')->table('session')->delete();
    vbbStoreSession(md5('wrong'), $vector['expected']['IPADDRESS']);                     // host right, idhash wrong
    expect(vbbUser(vbbRequest($vector['server'])))->toBeNull();
});
